<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';require_method('POST');$u=current_user();require_csrf();$id=string_value(input(),'id',36);$campaign=authorize_campaign($id);$pdo=db();$pdo->beginTransaction();try{$pdo->prepare("INSERT IGNORE INTO lead_campaign_claims (tenant_id,lead_id,campaign_id) SELECT tenant_id,lead_id,campaign_id FROM campaign_recipients WHERE tenant_id=? AND campaign_id=? AND status='FAILED' AND attempts<3")->execute([$u['tenant_id'],$campaign['id']]);$s=$pdo->prepare("UPDATE campaign_recipients r JOIN lead_campaign_claims cl ON cl.tenant_id=r.tenant_id AND cl.lead_id=r.lead_id AND cl.campaign_id=r.campaign_id SET r.status='RETRY',r.available_at=UTC_TIMESTAMP(),r.last_error=NULL WHERE r.tenant_id=? AND r.campaign_id=? AND r.status='FAILED' AND r.attempts<3");$s->execute([$u['tenant_id'],$campaign['id']]);$count=$s->rowCount();if($count<1)throw new ApiError(409,'No failed recipients are available to retry; they may be reserved by another active campaign.');$pdo->prepare("UPDATE campaigns SET status='QUEUED',pending_count=pending_count+?,failed_count=GREATEST(failed_count-?,0),completed_at=NULL WHERE tenant_id=? AND id=?")->execute([$count,$count,$u['tenant_id'],$campaign['id']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}audit('campaign.failed_retried','campaign',$id,['count'=>$count]);respond(['queued'=>$count]);
